from pathlib import Path
p=Path('app.js')
s=p.read_text()
# Newest active map is highest number; old/new order remains chronological in source, numbering is reverse.
s=s.replace("function activeMapNumber(mapId){const maps=DB.maps.filter(m=>m.archived!==true).slice().sort((a,b)=>{const na=Number(String(a.map_id||'').match(/(\\d+)(?:$)/)?.[1]||0),nb=Number(String(b.map_id||'').match(/(\\d+)(?:$)/)?.[1]||0);return na-nb||matchOrder(DB.matches.find(x=>x.match_id===a.match_id))-matchOrder(DB.matches.find(x=>x.match_id===b.match_id))||Number(a.map_index||0)-Number(b.map_index||0)});const i=maps.findIndex(m=>m.map_id===mapId);return i<0?null:i+1}", "function activeMapNumber(mapId){const maps=DB.maps.filter(m=>m.archived!==true).slice().sort((a,b)=>{const na=Number(String(a.map_id||'').match(/(\\d+)(?:$)/)?.[1]||0),nb=Number(String(b.map_id||'').match(/(\\d+)(?:$)/)?.[1]||0);return na-nb||matchOrder(DB.matches.find(x=>x.match_id===a.match_id))-matchOrder(DB.matches.find(x=>x.match_id===b.match_id))||Number(a.map_index||0)-Number(b.map_index||0)});const i=maps.findIndex(m=>m.map_id===mapId);return i<0?null:maps.length-i}")
# Player profile: AVG lowercase, colored K/D, recent map K/D-colored stats, MVP blue, no map count.
s=s.replace("<strong>AVG ${fmt(w.avg,2)}</strong><small>K/D ${fmt(w.kd,2)}</small>", "<strong>avg ${fmt(w.avg,2)}</strong><small>${kdMarkupValue(w.kd,'K/D ')}</small>")
s=s.replace("<strong>AVG ${fmt(e.avg,2)}</strong><small>K/D ${fmt(e.kd,2)}</small>", "<strong>avg ${fmt(e.avg,2)}</strong><small>${kdMarkupValue(e.kd,'K/D ')}</small>")
s=s.replace("return `<div class=\"map-history-row compact-row\"><div><b>${esc(r.map)}</b><span>${r.kills}/${r.deaths}/${r.assists}</span></div><strong>MVP · ${esc(mapMvp(r.map_id))}</strong><span class=\"map-history-index\">${n?`#${n}`:''}</span></div>`", "return `<div class=\"map-history-row compact-row\"><div><b class=\"map-history-name\">${esc(r.map)}</b><span class=\"map-kda ${kdClass(r.kills,r.deaths)}\">${r.kills}/${r.deaths}/${r.assists}</span></div><strong class=\"map-mvp-link\">MVP · ${esc(mapMvp(r.map_id))}</strong><span class=\"map-history-index\">${n?`#${n}`:''}</span></div>`")
# History all maps: remove MVP, white map name, blue number, keep score.
s=s.replace("<div><b>${n?`#${n} · `:''}${esc(m.map)}</b><span>${esc(mapMvp(m.map_id))}</span></div><strong>", "<div><b><span class=\"map-history-index\">${n?`#${n}`:''}</span><span class=\"map-history-name\">${esc(m.map)}</span></b></div><strong>")
# Era heading casing and K/D colors done above; make the header itself less capsule-ish through CSS.
# Remove top quick roster entirely; bottom roster remains draggable.
start="  <div class=\"team-quick-add panel card\"><div class=\"section-head\"><div><h3>БЫСТРЫЙ НАБОР ИГРОКОВ</h3><div class=\"muted\">Клик по игроку: сначала A, затем B. Не нужно прокручивать список вниз.</div></div><span class=\"pill\">${allSelected.length}/10</span></div><input id=\"teamPlayerSearch\" class=\"control team-player-search\" placeholder=\"Поиск игрока...\"><div id=\"teamQuickPool\" class=\"team-quick-pool\">${roster.map(p=>`<button type=\"button\" class=\"team-quick-chip ${allSelected.includes(p.player_id)?'selected':''}\" data-name=\"${esc(p.display_name.toLowerCase())}\" onclick=\"addToTeam('${esc(p.player_id)}')\"><span>${esc(p.display_name)}</span><b>${fmt(index(p.player_id),1)}</b></button>`).join('')}</div></div>"
s=s.replace(start,'')
# Remove now-dead quick pool event hookup.
s=s.replace("$('#whatIfOut')?.addEventListener('change',e=>{state.whatIfOut=e.target.value;render()});\n  $('#whatIfIn')?.addEventListener('change',e=>{state.whatIfIn=e.target.value;render()});$('#teamMapSelect')?.addEventListener('change',e=>{state.teamMap=e.target.value;render()});$('#teamPlayerSearch')?.addEventListener('input',e=>{const q=e.target.value.trim().toLowerCase();document.querySelectorAll('#teamQuickPool .team-quick-chip').forEach(b=>b.style.display=!q||b.dataset.name.includes(q)?'':'none')});if($('#teamMapSelect'))$('#teamMapSelect').value=state.teamMap;", "$('#whatIfOut')?.addEventListener('change',e=>{state.whatIfOut=e.target.value;render()});\n  $('#whatIfIn')?.addEventListener('change',e=>{state.whatIfIn=e.target.value;render()});$('#teamMapSelect')?.addEventListener('change',e=>{state.teamMap=e.target.value;render()});if($('#teamMapSelect'))$('#teamMapSelect').value=state.teamMap;")
